<?php
require dirname(__DIR__).'/includes/bootstrap.php';verify_csrf();ensure_runtime_schema();
$id=(int)($_POST['id']??0);if($id>0)require_permission('drivers.edit');else require_permission('drivers.create');
$date=trim((string)($_POST['activity_date']??''));$customers=max(0,(int)($_POST['customers_registered']??0));$drivers=max(0,(int)($_POST['drivers_registered']??0));
$dt=DateTimeImmutable::createFromFormat('Y-m-d',$date);if(!$dt||$dt->format('Y-m-d')!==$date){flash('error','Choose a valid registration date.');redirect('drivers.php');}
try{$pdo=db();if($id>0){$existing=$pdo->prepare('SELECT id FROM daily_growth_counts WHERE id=?');$existing->execute([$id]);if(!$existing->fetchColumn())throw new RuntimeException('Daily count record was not found.');$conflict=$pdo->prepare('SELECT id FROM daily_growth_counts WHERE activity_date=? AND id<>?');$conflict->execute([$date,$id]);if($conflict->fetchColumn())throw new RuntimeException('A count record already exists for this date. Edit that record instead.');$pdo->prepare('UPDATE daily_growth_counts SET activity_date=?,customers_registered=?,drivers_registered=?,updated_by=? WHERE id=?')->execute([$date,$customers,$drivers,current_user_id(),$id]);$recordId=$id;$action='growth_count.updated';}else{$pdo->prepare('INSERT INTO daily_growth_counts(activity_date,customers_registered,drivers_registered,created_by,updated_by) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE customers_registered=VALUES(customers_registered),drivers_registered=VALUES(drivers_registered),updated_by=VALUES(updated_by)')->execute([$date,$customers,$drivers,current_user_id(),current_user_id()]);$q=$pdo->prepare('SELECT id FROM daily_growth_counts WHERE activity_date=?');$q->execute([$date]);$recordId=(int)$q->fetchColumn();$action='growth_count.saved';}audit($action,'daily_growth_count',$recordId,['date'=>$date,'customers'=>$customers,'drivers'=>$drivers]);flash('success','Daily customer and driver counts saved successfully.');}catch(Throwable $e){flash('error',$e->getMessage());}redirect('drivers.php');
